local CommRoleBonusLayoutGroup = Class('CommRoleBonusLayoutGroup')
local NodePath = "Game.Behaviours.CommRoleBonusLayoutGroupNode"

function CommRoleBonusLayoutGroup:__init()
	self.nodeEnv = {}
end

function CommRoleBonusLayoutGroup:Awake()
	self:InitNodeEvn()
