function CommRoleBonusLayoutGroup:InitNodeEvn()
	--CfUtils.SetActive(self.RoleBonusToggleNode.gameObject,false)
	local env = CfUtils.GetLuaScr(self.RoleBonusToggleNode,NodePath)
	if isNotNull(env) then
		table.insert(self.nodeEnv,env)
