end

function CommRoleBonusLayoutGroup:__delete()
	self.nodeEnv = nil
end

function CommRoleBonusLayoutGroup:RefreshShow(data,isDown, excludeDialogs)
	if table.count(checkTable(data)) <= 0 then
		CfUtils.SetActive(self.controller.gameObject,false)
		return
	end
	for i, v in pairs(data) do
		if self.nodeEnv[i] then
			self.nodeEnv[i]:RefreshShow(v, isDown, excludeDialogs)
		else
			local node = CfUtils.InstantiateGo(self.RoleBonusToggleNode, self.controller.gameObject, false)
			if node then
				local env = CfUtils.GetLuaScr(node,NodePath)
				if env then
					table.insert(self.nodeEnv,env)
					env:RefreshShow(v, isDown, excludeDialogs)
				end
			end
		end
	end
	CfUtils.SetActive(self.controller.gameObject,true)
end

